from unittest.mock import patch

def train_with_initial(pairs, **kwargs):
    # Observe the actual starting head; do not prescribe its initialization or RNG use.
    initial = {}
    original_init = RewardModel.__init__
    def capture_init(model, input_dim):
        original_init(model, input_dim)
        initial[id(model)] = weights(model, input_dim)
    with patch.object(RewardModel, '__init__', capture_init):
        model, history = train_reward_model(pairs, **kwargs)
    assert id(model) in initial, 'Return a freshly constructed RewardModel'
    return model, history, initial[id(model)]

def oracle(pairs, initial_w, epochs, batch_size, lr):
    delta = torch.stack([c - r for (c, r) in pairs])
    w = initial_w.clone()
    def evaluate():
        z = (delta @ w).tolist()
        return sum((math.log1p(math.exp(-v)) if v >= 0 else -v + math.log1p(math.exp(v)) for v in z)) / len(z)
    history = [evaluate()]
    for _ in range(epochs):
        for start in range(0, len(pairs), batch_size):
            x = delta[start:start + batch_size]
            gradient = (-torch.sigmoid(-(x @ w))[:, None] * x).mean(0)
            w = w - lr * gradient
        history.append(evaluate())
    return w, history

pairs = [record([1.0, 0.0], [-1.0, 0.0]),
